import java.util.*;
import java.io.*;
import java.text.*;

public class E1342 {

	static long mod = 998244353;

	static long modPow(long a, long e) // O(log e)
	{
		a %= mod;
		long res = 1;
		while (e > 0) {
			if ((e & 1) == 1)
				res = (res * a) % mod;
			a = (a * a) % mod;
			e >>= 1;
		}
		return res;
	}

	static long[] fac, invfac;

	public static long nck(long n, long k) {
		return fac[(int) n] * invfac[(int) k] % mod * invfac[(int) (n - k)] % mod;
	}

	public static void main(String[] args) throws IOException {
		Scanner sc = new Scanner(System.in);
		PrintWriter pw = new PrintWriter(System.out);
		long n = sc.nextInt();
		long k = sc.nextLong();
		if (k >= n) {
			pw.println(0);
			pw.close();
			return;
		}
		fac = new long[(int) n + 1];
		invfac = new long[(int) n + 1];
		fac[0] = 1;
		for (int i = 1; i < fac.length; i++) {
			fac[i] = (i * fac[i - 1]) % mod;
		}
		invfac[0] = 1;
		for (int i = 1; i < invfac.length; i++) {
			invfac[i] = (invfac[i - 1] * modPow(i, mod - 2)) % mod;
		}
		long m = n - k;
		long posans = 0;
		long negans = 0;
		for (int i = 0; i <= m; i++) {
			if (i % 2 == 0) {
				posans += modPow(m - i, n) * nck(m, i) % mod;
				posans %= mod;
			} else {
				negans += modPow(m - i, n) * nck(m, i) % mod;
				negans %= mod;
			}
		}
		long ans = (posans - negans + 2 * mod) % mod;
		ans *= nck(n, m);
		ans %= mod;
		if (m != n) {
			ans *= 2;
		}
		ans %= mod;
		pw.println(ans);
		pw.close();
	}

	static class Scanner {
		StringTokenizer st;
		BufferedReader br;

		public Scanner(InputStream s) {
			br = new BufferedReader(new InputStreamReader(s));
		}

		public Scanner(FileReader r) {
			br = new BufferedReader(r);
		}

		public String next() throws IOException {
			while (st == null || !st.hasMoreTokens())
				st = new StringTokenizer(br.readLine());
			return st.nextToken();
		}

		public int nextInt() throws IOException {
			return Integer.parseInt(next());
		}

		public long nextLong() throws IOException {
			return Long.parseLong(next());
		}

		public String nextLine() throws IOException {
			return br.readLine();
		}

		public double nextDouble() throws IOException {
			return Double.parseDouble(next());
		}

		public int[] nextIntArr(int n) throws IOException {
			int[] arr = new int[n];
			for (int i = 0; i < arr.length; i++)
				arr[i] = nextInt();
			return arr;
		}

		public boolean ready() throws IOException {
			return br.ready();
		}

	}
}

